          {capture $c_3}
            {=og_text(og_get($v_f, ['text']))}
          {/capture}
          {=og_include('compose/Text.latte', ['size' => 'sm', 'class' => 'text-muted-foreground', 'children' => (string) $c_3])|noescape}
        {/capture}
        {=og_include('compose/Stack.latte', ['gap' => '2', 'class' => 'min-w-0', 'children' => (string) $c_4])|noescape}
      {/capture}
      {=og_include('compose/Group.latte', ['gap' => '4', 'align' => 'start', 'attrs' => og_attrs(['data-slot', 'feature-item']), 'children' => (string) $c_5])|noescape}
    {/if}
  {/foreach}
